Lesson: VII-M2-L06 - "Operatori aritmetici și expresii" (Grade VII, Romanian curriculum)

Knowledge content:
{
  "levels": [
    {
      "level": "general",
      "concepts": [
        "Calculatorul poate efectua operații matematice cu numere și variabile",
        "Rezultatul poate fi stocat într-o variabilă sau afisat direct"
      ]
    },
    {
      "level": "intermediate",
      "concepts": [
        "Operatorii: + (adunare), - (scadere), * (inmultire), / (impartire)",
        "Operatorul % (modulo) - restul impartirii (doar pentru intregi)",
        "Ordinea operatiilor: *, /, % au prioritate față de +, -",
        "Parantezele ( ) modifică ordinea evaluarii"
      ]
    },
    {
      "level": "specific",
      "concepts": [
        "Impartirea intreaga: 7 / 2 = 3 (dacă ambele sunt int)",
        "Impartirea reala: 7.0 / 2 = 3.5 (dacă cel putin unul e float)",
        "Operatorii compusi: +=, -=, *=, /= (x += 5 echivalent cu x = x + 5)",
        "Incrementare/decrementare: ++, -- (x++ echivalent cu x = x + 1)",
        "Expresii complexe: rezultat = (a + b) * c / 2;"
      ]
    }
  ]
}

Instructional content:
{
  "hook": {
    "duration_minutes": 4,
    "activity": "Puzzle matematic: 'Calculatorul zice ca 7 / 2 = 3. A gresit?' Lasati elevii să discute. Dezvaluiti: 'Nu a gresit - e impartire intreaga! Astazi învățăm regulile matematicii în C++, care nu sunt 100% ca la școală.'",
    "connection_to_prior": "Știm să citim numere și să le stocam. Acum învățăm să facem ceva util cu ele - calcule!"
  },
  "micro_lecture": {
    "duration_minutes": 12,
    "key_terms": [
      {
        "term": "Operator aritmetic",
        "definition": "Simbol care efectueaza o operație matematica asupra numerelor",
        "analogy": "Ca semnele +, -, x, : din matematica, dar scrise usor diferit"
      },
      {
        "term": "Expresie",
        "definition": "Combinatie de valori, variabile și operatori care produce un rezultat",
        "analogy": "E ca o formula matematica: (a + b) / 2"
      },
      {
        "term": "Modulo (%)",
        "definition": "Operatorul care returneaza restul impartirii intregi",
        "analogy": "10 % 3 = 1 pentru ca 10 / 3 = 3 rest 1"
      },
      {
        "term": "Impartire intreaga vs reala",
        "definition": "int / int = int (fara zecimale); dacă unul e float, rezultatul e float",
        "analogy": "7 / 2 = 3 (intreg), dar 7.0 / 2 = 3.5 (real)"
      },
      {
        "term": "Prioritatea operatorilor",
        "definition": "Ordinea în care se executa operatiile: *, /, % inaintea +, -",
        "analogy": "Ca în matematica: inmultirea și impartirea au prioritate"
      },
      {
        "term": "Operatori compusi (+=, -=)",
        "definition": "Scurtatura pentru operație și atribuire: x += 5 înseamnă x = x + 5",
        "analogy": "E o prescurtare pentru a nu scrie variabilă de doua ori"
      }
    ],
    "explain_like_im_12": "Gandeste-te la C++ ca la un calculator foarte literal. Dacă ii dai 7 / 2 și ambele sunt numere intregi, el zice '3' pentru ca nu știe de zecimale în acest caz. Dacă vrei 3.5, trebuie să-i spui ca lucrezi cu numere reale (7.0 / 2). Operatorul % e super util - iti spune restul: 10 % 3 = 1, pentru ca 10 impartit la 3 da 3 și rest 1. E perfect pentru a verifică dacă un numar e par: dacă n % 2 == 0, e par!",
    "visual_aids": [
      "Tabel operatori: simbol, nume, exemplu, rezultat",
      "Diagrama prioritate operații (piramida)",
      "Exemple de impartire intreaga vs reala, side by side"
    ]
  },
  "practice_guided": {
    "duration_minutes": 18,
    "tasks": [
      {
        "task": "Experimentam cu operatorii de baza",
        "steps": [
          "Creati un program nou",
          "Declarati int a = 15, b = 4;",
          "Afisati: cout << a + b << endl; // adunare",
          "Afisati: cout << a - b << endl; // scadere",
          "Afisati: cout << a * b << endl; // inmultire",
          "Afisati: cout << a / b << endl; // impartire intreaga",
          "Afisati: cout << a % b << endl; // modulo (restul)",
          "Discutati fiecare rezultat"
        ],
        "teacher_support": "Intrebati elevii ce asteptau la a / b (3.75 vs 3)"
      },
      {
        "task": "Impartire intreaga vs reala",
        "steps": [
          "Declarati float c = 15.0, d = 4;",
          "Afisati: cout << c / d << endl; // acum da 3.75!",
          "Testati: cout << 15 / 4 << endl; vs cout << 15.0 / 4 << endl;",
          "Regula: dacă vrei zecimale, cel putin un numar trebuie să fie float"
        ],
        "teacher_support": "Vizualizati diferenta pe proiector"
      },
      {
        "task": "Prioritatea și parantezele",
        "steps": [
          "Calculati: cout << 2 + 3 * 4 << endl; // rezultat: 14 (nu 20!)",
          "Cu paranteze: cout << (2 + 3) * 4 << endl; // acum: 20",
          "Exemplu practic - media: cout << (10 + 8 + 9) / 3 << endl;",
          "De ce e important? Fara paranteze: 10 + 8 + 9 / 3 = 10 + 8 + 3 = 21 (gresit!)"
        ],
        "teacher_support": "Desenati arborele de evaluare pe tabla"
      },
      {
        "task": "Operatori compusi și incrementare",
        "steps": [
          "Declarati int scor = 100;",
          "scor = scor + 10; apoi cout << scor; // 110",
          "Rescrieti: scor += 50; cout << scor; // 160",
          "Incrementare: scor++; cout << scor; // 161",
          "Decrementare: scor--; cout << scor; // 160"
        ],
        "teacher_support": "Aratati ca e doar o scurtatura, face același lucru"
      }
    ],
    "success_criteria": [
      "Elevul poate folosi toti operatorii de baza: +, -, *, /, %",
      "Elevul înțelege diferenta dintre impartirea intreaga și cea reala",
      "Elevul poate scrie expresii cu paranteze pentru ordinea dorita"
    ]
  },
  "practice_independent": {
    "duration_minutes": 10,
    "levels": {
      "minim": [
        {
          "task": "Scrie un program care citeste doua numere intregi și afișează suma, diferenta, produsul și catul lor.",
          "expected_output": "Program cu cin pentru 2 numere, 4 cout-uri cu rezultate"
        }
      ],
      "standard": [
        {
          "task": "Creează un calculator de medie: citeste 4 note (float), calculează media, și afișează-o cu mesaj. Atenție la impartire!",
          "expected_output": "Program cu 4 cin-uri, calcul media corectă (suma / 4.0), afisare"
        }
      ],
      "performanta": [
        {
          "task": "Calculator de timp: citeste un numar de secunde (ex: 3665). Calculează și afișează câte ore, minute și secunde reprezintă. Hint: folosește / și % combinat.",
          "expected_output": "Program care transformă 3665 secunde în 1 ora, 1 minut, 5 secunde"
        }
      ]
    }
  },
  "wrap_up": {
    "duration_minutes": 6,
    "exit_ticket": {
      "minim": [
        "Ce rezultat da 10 / 3 dacă ambele sunt int?",
        "Ce operator folosim pentru restul impartirii?"
      ],
      "standard": [
        "Scrie expresia pentru media aritmetica a variabilelor a, b, c."
      ],
      "performanta": [
        "Cum verifici dacă un numar n este par folosind operatorul %?"
      ]
    },
    "preview_next": "Saptamana viitoare - recapitulare completă și exercitii integrate care combina tot ce am învățat!"
  }
}

